// Generated by AI.
using UnityEngine;
using UnityEngine.SceneManagement;

namespace GrindHero.Presentation.World
{
    public sealed class CombatFloatText : MonoBehaviour
    {
        private float _remaining = 0.8f;
        private TextMesh _text;
        private Color _color;

        public static void Show(Vector3 position, string value, Color color, Transform sceneOwner)
        {
            var item = new GameObject("Combat number", typeof(TextMesh), typeof(CombatFloatText));
            SceneManager.MoveGameObjectToScene(item, sceneOwner.gameObject.scene);
            item.transform.position = position + Vector3.up * 2.45f;
            var effect = item.GetComponent<CombatFloatText>();
            effect._text = item.GetComponent<TextMesh>();
            effect._color = color;
            effect._text.text = value;
            effect._text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            effect._text.fontSize = 48;
            effect._text.characterSize = 0.065f;
            effect._text.anchor = TextAnchor.MiddleCenter;
            effect._text.color = color;
            effect._text.GetComponent<Renderer>().sharedMaterial = effect._text.font.material;
            item.AddComponent<WorldLabel>();
        }

        private void Update()
        {
            _remaining -= Time.deltaTime;
            transform.position += Vector3.up * (Time.deltaTime * 0.8f);
            _text.color = new Color(_color.r, _color.g, _color.b, Mathf.Clamp01(_remaining * 3f));
            if (_remaining <= 0f)
            {
                Destroy(gameObject);
            }
        }
    }
}
